// Block (composition) — a readable article heading with taxonomy and author metadata.
// Badge and Avatar own their look; Stack owns all grouping and alignment.
import type { Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Badge } from "../components/Badge";
import { Stack } from "../layouts/Stack";
import "./ArticleHeader.css";

export interface ArticleHeaderProps {
  /** Article title. */
  title: string;
  /** Supporting summary shown below the title. */
  subtitle?: string;
  /** Optional author identity. */
  author?: {
    name: string;
    avatarSrc?: string;
  };
  /** Human-readable publication date. */
  date?: string;
  /** Taxonomy labels shown above the title. */
  tags?: string[];
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ArticleHeader({
  title,
  subtitle,
  author,
  date,
  tags,
  className,
  ref,
}: ArticleHeaderProps) {
  return (
    <Stack
      as="header"
      ref={ref}
      gap="small"
      className={className ? `sd-articleheader ${className}` : "sd-articleheader"}
    >
      {tags && tags.length > 0 && (
        <Stack direction="row" gap="x-small" wrap className="sd-articleheader__tags">
          {tags.map((tag) => (
            <Badge key={tag}>{tag}</Badge>
          ))}
        </Stack>
      )}
      {/* spacing: attachment — the tags annotate the title below them.
          The name and its supporting line are ONE unit, so they group at `x-small` while the
          section around them sits a rung looser. */}
      <>
        <Stack gap="x-small" className="sd-articleheader__heading">
          <h1 className="sd-articleheader__title sd-type-display-medium">{title}</h1>
          {subtitle && (
            <p className="sd-articleheader__subtitle sd-type-body-medium">{subtitle}</p>
          )}
        </Stack>
      </>
      {(author || date) && (
        <Stack direction="row" align="center" gap="small" wrap className="sd-articleheader__meta-row">
          {author && (
            <>
              <Avatar src={author.avatarSrc} size="small" alt={author.name}>
                {author.name.charAt(0)}
              </Avatar>
              <span className="sd-articleheader__meta sd-type-caption-medium">
                {author.name}
              </span>
            </>
          )}
          {date && <span className="sd-articleheader__meta sd-type-caption-medium">{date}</span>}
        </Stack>
      )}
    </Stack>
  );
}

/* ArticleHeader.css — .sd-articleheader (Block)
   Arrangement only: fills the column it is given; the page sets a readable measure on the grid. */
.sd-articleheader {
  width: 100%;
}

.sd-articleheader__title,
.sd-articleheader__subtitle,
.sd-articleheader__meta {
  margin: 0;
}

.sd-articleheader__meta {
  color: var(--sd-color-text-muted);
}

.sd-articleheader__subtitle {
  color: var(--sd-color-text-muted);
}
